<script setup>
import { ref, computed } from 'vue'
const cwd = ref('/var/www/studio'), query = ref(''), selected = ref(null), content = ref(''), feedback = ref(''), error = ref('')
const entries = ref([
  { name: 'public', parent: '/var/www/studio', type: 'folder', size: '—', mode: '0755' },
  { name: 'storage', parent: '/var/www/studio', type: 'folder', size: '—', mode: '0755' },
  { name: 'README.md', parent: '/var/www/studio', type: 'file', size: '142 B', mode: '0644', content: '# Example website\n\nDesign preview only. These files exist only in browser memory.\n' },
  { name: 'index.html', parent: '/var/www/studio/public', type: 'file', size: '96 B', mode: '0644', content: '<!doctype html>\n<html lang="en">\n  <title>Example website</title>\n  <h1>Hello from AxionPanel</h1>\n</html>\n' },
  { name: 'robots.txt', parent: '/var/www/studio/public', type: 'file', size: '24 B', mode: '0644', content: 'User-agent: *\nDisallow:\n' }
])
const folders = ['/var/www/studio', '/var/www/studio/public', '/var/www/studio/storage']
const visible = computed(() => entries.value.filter(e => e.parent === cwd.value && e.name.toLowerCase().includes(query.value.toLowerCase())))
function navigate(path) { cwd.value = path; selected.value = null; query.value = ''; error.value = '' }
function openEntry(entry) { if (entry.type === 'folder') navigate(entry.parent + '/' + entry.name); else { selected.value = entry; content.value = entry.content; error.value = '' } }
function saveFile() { if (!selected.value) return; if (content.value.length > 100000) { error.value = 'Example editor is limited to 100 KB.'; return }; selected.value.content = content.value; selected.value.size = content.value.length + ' B'; error.value = ''; feedback.value = 'Preview only — example content updated in memory. No filesystem write occurred.' }
function resetEditor() { content.value = selected.value.content; error.value = ''; feedback.value = 'Preview only — unsaved example edits discarded.' }
</script>
<template>
  <main class="w-full pt-16 min-h-screen" style="background: rgb(var(--c-surface))">
    <section><header class="page-heading"><div><p class="ax-label">Workspace / in-memory example files</p><h1>File Manager</h1><p class="ax-sub">Browse a sample document root and edit text without touching a filesystem.</p></div><span class="ax-pill ax-pill-info">Preview only · browser memory</span></header>
      <p v-if="feedback" class="notice ax-pill ax-pill-info" role="status">{{ feedback }}</p>
      <div class="file-layout ax-card"><nav class="tree" aria-label="Example folder tree"><p class="ax-label">Example workspace</p><button v-for="folder in folders" :key="folder" class="folder" :class="{ active: cwd === folder, nested: folder !== folders[0] }" @click="navigate(folder)"><span aria-hidden="true" class="material-symbols-outlined">{{ cwd === folder ? 'folder_open' : 'folder' }}</span>{{ folder === folders[0] ? 'studio' : folder.split('/').pop() }}</button><div class="ax-divider"></div><p class="ax-sub">Sandbox root</p><code class="ax-sub">/var/www/studio</code><p class="ax-sub">No upload, execution, or server access is available here.</p></nav>
        <div class="file-main"><div class="ax-card-pad ax-hd"><div><p class="ax-label">Current directory</p><span class="ax-mono path">{{ cwd }}</span></div><label><span class="ax-label">Search files</span><input v-model="query" class="ax-input" type="search" placeholder="Filter this folder"></label></div><div class="table-scroll"><table class="ax-table"><thead><tr><th>Name</th><th>Size</th><th>Permissions</th><th>Owner</th><th></th></tr></thead><tbody><tr v-for="entry in visible" :key="entry.name" :class="{ chosen: selected === entry }"><td><button class="file-name" @click="openEntry(entry)"><span aria-hidden="true" class="material-symbols-outlined">{{ entry.type === 'folder' ? 'folder' : 'description' }}</span>{{ entry.name }}</button></td><td class="ax-mono">{{ entry.size }}</td><td class="ax-mono">{{ entry.mode }}</td><td class="ax-mono">www-data</td><td><button class="ax-btn ax-btn-ghost" @click="openEntry(entry)">{{ entry.type === 'folder' ? 'Open folder' : 'Edit example' }}</button></td></tr><tr v-if="!visible.length"><td colspan="5" class="empty"><span aria-hidden="true" class="material-symbols-outlined">folder_off</span><p>{{ query ? 'No matching example files.' : 'This example folder is empty.' }}</p><button v-if="query" class="ax-btn ax-btn-ghost" @click="query = ''">Clear search</button></td></tr></tbody></table></div>
          <section v-if="selected" class="editor"><div class="ax-hd"><div><span class="ax-label">Text editor / example</span><h2 class="ax-title">{{ selected.name }}</h2></div><span class="ax-pill" :class="content === selected.content ? 'ax-pill-dim' : 'ax-pill-warn'">{{ content === selected.content ? 'No pending edits' : 'Unsaved example edits' }}</span></div><label for="file-content" class="ax-label">Example file contents (plain text only)</label><textarea id="file-content" v-model="content" class="ax-textarea code-editor" rows="12" spellcheck="false"></textarea><p v-if="error" role="alert" class="error">{{ error }}</p><div class="panel-footer"><span class="ax-sub">{{ content.split('\n').length }} lines · never executed or rendered as HTML</span><div class="page-actions"><button class="ax-btn ax-btn-ghost" @click="resetEditor">Discard edits</button><button class="ax-btn ax-btn-primary" @click="saveFile">Save example · Preview only</button></div></div></section><div v-else class="editor-empty"><span aria-hidden="true" class="material-symbols-outlined">edit_document</span><p>Select an example text file to open the editor.</p><span class="ax-sub">All edits disappear when the page reloads.</span></div>
        </div>
      </div>
    </section>
  </main>
</template>
<style scoped>
.file-layout{display:grid;grid-template-columns:210px minmax(0,1fr);overflow:hidden}.tree{padding:20px;background:rgb(var(--c-surface-container-lowest));border-right:1px solid rgb(var(--c-outline-variant)/.3)}.folder{display:flex;gap:8px;align-items:center;width:100%;padding:12px 8px;background:none;border:0;color:rgb(var(--c-on-surface-variant));text-align:left;font:12px 'JetBrains Mono',monospace;cursor:pointer;border-radius:4px}.nested{padding-left:26px}.folder.active{background:rgb(var(--c-primary)/.1);color:rgb(var(--c-primary))}.folder .material-symbols-outlined{font-size:19px}.file-name{display:flex;align-items:center;gap:8px;background:none;border:0;color:rgb(var(--c-primary));font:12px 'JetBrains Mono',monospace;cursor:pointer;text-align:left}.file-name span{font-size:19px}.chosen td{background:rgb(var(--c-primary)/.04)}.path{font-size:12px;overflow-wrap:anywhere}.editor{padding:20px;border-top:1px solid rgb(var(--c-outline-variant)/.3)}.editor h2{margin:6px 0 0}.code-editor{margin-top:10px;line-height:23px;tab-size:2;background:rgb(var(--c-surface-container-lowest));resize:vertical}.editor-empty,.empty{text-align:center;padding:45px 20px;font-size:13px;color:rgb(var(--c-outline))}.editor-empty>span:first-child{font-size:34px;color:rgb(var(--c-primary))}.notice{white-space:normal;margin-bottom:16px}.error{color:rgb(var(--c-error));font-size:12px}@media(max-width:750px){.file-layout{grid-template-columns:1fr}.tree{border-right:0;border-bottom:1px solid rgb(var(--c-outline-variant)/.3)}.folder{display:inline-flex;width:auto}.tree .ax-divider,.tree>p:not(:first-child),.tree>code{display:none}.ax-hd{flex-wrap:wrap}}button:focus-visible{outline:2px solid rgb(var(--c-primary));outline-offset:3px}
</style>
